`define TB_CHECK(COND, MSG) \
  begin \
    tb_pkg::n_checks++; \
    if ((COND) !== 1'b1) tb_pkg::fail($sformatf MSG); \
  end

`define TB_CHECK_EQ(GOT, EXP, WHAT) \
  begin \
    tb_pkg::n_checks++; \
    if ((GOT) !== (EXP)) \
      tb_pkg::fail($sformatf("%s: got 'h%0h, expected 'h%0h", WHAT, GOT, EXP)); \
  end

