`define TB_DUMP(TOP) \
  initial begin $fsdbDumpfile("dump.fsdb"); $fsdbDumpvars(0, TOP); end
`else
`define TB_DUMP(TOP) \
  initial begin if ($test$plusargs("VCD")) begin $dumpfile("dump.vcd"); $dumpvars(0, TOP); end end
`endif

`endif

