`timescale 1ns/1ps

package traffic_pkg;
  import noc_pkg::*;

  typedef enum int {
    PAT_UNIFORM   = 0,
    PAT_TRANSPOSE = 1,
    PAT_BITCOMP   = 2,
    PAT_BITROT    = 3,
    PAT_SHUFFLE   = 4,
    PAT_TORNADO   = 5,
    PAT_NEIGHBOR  = 6,
    PAT_HOTSPOT   = 7,
    PAT_REGION    = 8,
    PAT_PHASE     = 9
  } pattern_e;

  localparam int NUM_PATTERNS = 10;

  typedef struct packed {
    logic [31:0]          seq;        // per-source sequence number
    logic [31:0]          t_create;   // cycle it was created
    node_id_t             dst;
    logic [PKT_LEN_W-1:0] len;        // 1 or 5 flits
  } pkt_t;

  /* verilator lint_off UNUSEDSIGNAL */
  /* verilator lint_off UNUSEDPARAM */
  int       mesh_n    = 4;
  pattern_e pattern   = PAT_UNIFORM;
  real      rate      = 0.0;            // packets per node per cycle
  real      p_data    = 1.0 / 3.0;      // share of 5-flit packets (P_DATA)
  int       hot_node  = -1;             // -1: the centre node (n/2, n/2)
  real      hot_frac  = 0.2;
  int       region_n  = 0;              // 0: n/2 (4 on 8x8, as REGION_N)
  real      p_local   = 0.5;
  pattern_e phase_a   = PAT_UNIFORM;
  pattern_e phase_b   = PAT_TRANSPOSE;
  int       phase_len = 500;
  bit       gen_on    = 1'b0;           // generators create packets only while set
  int       burst_id  = 0;
  int          period    = 0;
  int unsigned per_t0    = 0;
  localparam int FS_NONE = -1;
  localparam int FS_ALL  = -2;
  real      sink_stall_p = 0.0;
  int       fs_node      = FS_NONE;
  int unsigned fs_start  = 0;
  int unsigned fs_end    = 0;

  typedef struct packed {
    logic [7:0]           dst;
    logic [PKT_LEN_W-1:0] len;
  } dir_t;
  dir_t     dir_q [256][$];

  typedef struct packed {
    logic [7:0]  src;
    logic [7:0]  dst;
    logic [31:0] seq;
    logic [2:0]  len;
    logic [31:0] t_create;
    logic [31:0] t_tail;
    logic        byp;
  } dlog_t;
  bit       log_on = 1'b0;
  dlog_t    dlog [$];

  function automatic void direct(int src, int dst, int len);
    dir_t       d;
    logic [7:0] k;
    d.dst = 8'(dst);
    d.len = PKT_LEN_W'(len);
    k     = 8'(src);
    dir_q[k].push_back(d);
  endfunction
  /* verilator lint_on UNUSEDPARAM */
  /* verilator lint_on UNUSEDSIGNAL */

  function automatic string pat_name(pattern_e p);
    case (p)
      PAT_UNIFORM:   return "uniform";
      PAT_TRANSPOSE: return "transpose";
      PAT_BITCOMP:   return "bitcomp";
      PAT_BITROT:    return "bitrot";
      PAT_SHUFFLE:   return "shuffle";
      PAT_TORNADO:   return "tornado";
      PAT_NEIGHBOR:  return "neighbor";
      PAT_HOTSPOT:   return "hotspot";
      PAT_REGION:    return "region";
      default:       return "phase";
    endcase
  endfunction

  function automatic bit pat_parse(string s, output pattern_e p);
    p = PAT_UNIFORM;
    for (int i = 0; i < NUM_PATTERNS; i++) begin
      if (s == pat_name(pattern_e'(i))) begin
        p = pattern_e'(i);
        return 1'b1;
      end
    end
    return 1'b0;
  endfunction

  function automatic int id_bits(int n);
    return $clog2(n * n);
  endfunction

  function automatic int region_side(int n);
    if (region_n > 0) return region_n;
    return (n >= 2) ? n / 2 : 1;
  endfunction

  function automatic int hotspot(int n);
    if (hot_node >= 0) return hot_node;
    return (n / 2) * n + n / 2;
  endfunction

  function automatic int perm_dest(pattern_e p, int src, int n);
    int b, x, y, k, m;
    b = id_bits(n);
    m = (1 << b) - 1;
    x = src % n;
    y = src / n;
    k = (n + 1) / 2 - 1;                 // ceil(n/2) - 1
    case (p)
      PAT_TRANSPOSE: return x * n + y;
      PAT_BITCOMP:   return (~src) & m;
      PAT_BITROT:    return ((src >> 1) | ((src & 1) << (b - 1))) & m;
      PAT_SHUFFLE:   return ((src << 1) | (src >> (b - 1))) & m;
      PAT_TORNADO:   return ((y + k) % n) * n + (x + k) % n;
      PAT_NEIGHBOR:  return ((y + 1) % n) * n + (x + 1) % n;
      default:       return -1;
    endcase
  endfunction

  function automatic int dest_one(pattern_e p, int src, int n, int sid);
    int r, x0, y0, k, d;
    bit in_reg;
    case (p)
      PAT_UNIFORM: begin
        d = int'(tb_pkg::rng_below(sid, n * n));
        return d;
      end
      PAT_HOTSPOT: begin
        if (tb_pkg::rng_chance(sid, hot_frac)) return hotspot(n);
        d = int'(tb_pkg::rng_below(sid, n * n));
        return d;
      end
      PAT_REGION: begin
        r  = region_side(n);
        x0 = ((src % n) / r) * r;
        y0 = ((src / n) / r) * r;
        in_reg = 1'b1;
        if (r < n) in_reg = tb_pkg::rng_chance(sid, p_local);
        if (in_reg) begin
          k = int'(tb_pkg::rng_below(sid, r * r));
          return (y0 + k / r) * n + x0 + k % r;
        end
        k = int'(tb_pkg::rng_below(sid, n * n - r * r));
        for (int i = 0; i < n * n; i++) begin
          if ((i % n) >= x0 && (i % n) < x0 + r && (i / n) >= y0 && (i / n) < y0 + r) continue;
          if (k == 0) return i;
          k--;
        end
        return src;
      end
      default: return perm_dest(p, src, n);
    endcase
  endfunction

  function automatic int dest(pattern_e p, int src, int n, int unsigned cyc, int sid);
    pattern_e q;
    q = p;
    if (p == PAT_PHASE) begin
      q = ((cyc / int'(phase_len)) % 2 == 0) ? phase_a : phase_b;
      if (q == PAT_PHASE) q = PAT_UNIFORM;
    end
    return dest_one(q, src, n, sid);
  endfunction

  function automatic int pkt_len(int sid);
    if (tb_pkg::rng_chance(sid, p_data)) return MAX_PKT_FLITS;
    return 1;
  endfunction

  function automatic logic [31:0] head_check(int src, int unsigned seq, int dst, int len,
                                             int unsigned t_create);
    logic [63:0] z;
    z = tb_pkg::mix64({32'(src), 32'(seq)} ^ {32'(dst), 32'(t_create)} ^ {32'(len), 32'h5bd1_e995});
    return z[63:32] ^ z[31:0];
  endfunction

  function automatic logic [FLIT_DATA_W-1:0] body_data(int src, int unsigned seq, int idx);
    logic [63:0] a, b;
    a = tb_pkg::mix64({32'(src), 32'(seq)} ^ {32'(idx), 32'h0});
    b = tb_pkg::mix64(a ^ 64'hc2b2_ae3d_27d4_eb4f);
    return {a, b};
  endfunction

  function automatic flit_t make_flit(int src, pkt_t p, int idx);
    flit_t f;
    head_t h;
    f       = '0;
    f.vld   = 1'b1;
    if (p.len == 3'd1)                    f.ftype = FT_SINGLE;
    else if (idx == 0)                    f.ftype = FT_HEAD;
    else if (idx == int'(p.len) - 1)      f.ftype = FT_TAIL;
    else                                  f.ftype = FT_BODY;
    if (idx == 0) begin
      h          = '0;
      h.dst      = p.dst;
      h.src      = node_id_t'(src);
      h.cls      = (p.len == 3'd1) ? CLS_CTRL : CLS_DATA;
      h.len      = p.len;
      h.seq      = p.seq;
      h.t_create = p.t_create;
      h.check    = head_check(src, p.seq, int'(p.dst), int'(p.len), p.t_create);
      f.data     = h;
    end else begin
      f.data = body_data(src, p.seq, idx);
    end
    return f;
  endfunction

  function automatic int zero_load(int h, int len);
    return 4 * (h + 1) + 1 + (len - 1);
  endfunction

  function automatic int zero_load_byp(int h, int len);
    return 2 * h + 2 * len + 3;
  endfunction

  function automatic real mean_hops(pattern_e p, int n);
    longint s;
    int     d, cnt;
    s   = 0;
    cnt = 0;
    for (int a = 0; a < n * n; a++) begin
      if (p == PAT_UNIFORM) begin
        for (int b = 0; b < n * n; b++) begin
          s += longint'(hops(coord_t'(a % n), coord_t'(a / n), coord_t'(b % n), coord_t'(b / n)));
          cnt++;
        end
      end else begin
        d = perm_dest(p, a, n);
        s += longint'(hops(coord_t'(a % n), coord_t'(a / n), coord_t'(d % n), coord_t'(d / n)));
        cnt++;
      end
    end
    return real'(s) / real'(cnt);
  endfunction

endpackage

// =============================================================================
// ==== tb/common/scoreboard.sv
// =============================================================================
`timescale 1ns/1ps

package sb_pkg;
  import noc_pkg::*;

  typedef struct packed {
    node_id_t             dst;
    logic [PKT_LEN_W-1:0] len;
    logic [31:0]          t_create;
  } rec_t;

  rec_t            live [longint unsigned];   // packets in flight
  longint unsigned n_created     = 0;
  longint unsigned n_delivered   = 0;
  /* verilator lint_off UNUSEDSIGNAL */
  int unsigned     last_delivery = 0;         // cycle of the latest delivery
  /* verilator lint_on UNUSEDSIGNAL */

  function automatic longint unsigned key(int src, int unsigned seq);
    return (longint'(src) << 32) | longint'(seq);
  endfunction

  function automatic void add(int src, int unsigned seq, int dst, int len, int unsigned t_create);
    rec_t r;
    longint unsigned k;
    k = key(src, seq);
    if (dst < 0 || dst > 255 || !(len == 1 || len == MAX_PKT_FLITS)) begin
      tb_pkg::fail($sformatf("scoreboard: packet %0d.%0d has destination %0d and length %0d", src, seq, dst, len));
      return;
    end
    if (live.exists(k) != 0) begin
      tb_pkg::fail($sformatf("scoreboard: packet %0d.%0d created twice", src, seq));
      return;
    end
    r.dst      = node_id_t'(dst);
    r.len      = PKT_LEN_W'(len);
    r.t_create = t_create;
    live[k]    = r;
    n_created++;
  endfunction

  function automatic bit take(int src, int unsigned seq, output rec_t r);
    longint unsigned k;
    k = key(src, seq);
    r = '0;
    if (live.exists(k) == 0) return 1'b0;
    r = live[k];
    live.delete(k);
    return 1'b1;
  endfunction

  function automatic void delivered(int unsigned cyc);
    n_delivered++;
    last_delivery = cyc;
  endfunction

  function automatic longint unsigned outstanding();
    return n_created - n_delivered;
  endfunction

endpackage

// =============================================================================
// ==== tb/common/stats.sv
// =============================================================================
`timescale 1ns/1ps

package stats_pkg;

  localparam int HIST     = 4096;
  localparam int FLOW_MIN = 10;

  int unsigned     w_start = 0, w_end = 0;
  int              n_nodes = 1;
  longint unsigned off_flits, acc_flits;
  longint unsigned m_pkts, m_flits, m_left;    // measured: created, flits, not yet delivered
  longint unsigned lat_sum, lat_max;
  longint unsigned zl_sum, zl_hits;           // zero-load latency of the packets measured; how many met it
  longint unsigned byp_pkts, byp_flits;       // measured packets (flits) delivered by bypass
  longint unsigned hist [HIST];
  longint unsigned src_flits [256];
  longint unsigned flow_sum [int];
  longint unsigned flow_cnt [int];
  longint unsigned tr_pkts, tr_lat;           // every delivery since trace_take (PERF's +TRACE, B8)

  function automatic void reset(int nodes);
    n_nodes   = nodes;
    w_start   = 0;
    w_end     = 0;
    off_flits = 0;
    acc_flits = 0;
    m_pkts    = 0;
    m_flits   = 0;
    m_left    = 0;
    lat_sum   = 0;
    lat_max   = 0;
    zl_sum    = 0;
    zl_hits   = 0;
    byp_pkts  = 0;
    byp_flits = 0;
    for (int i = 0; i < HIST; i++) hist[i] = 0;
    for (int i = 0; i < 256; i++) src_flits[i] = 0;
    flow_sum.delete();
    flow_cnt.delete();
    tr_pkts   = 0;
    tr_lat    = 0;
  endfunction

  function automatic void trace_take(output longint unsigned n, output longint unsigned s);
    n       = tr_pkts;
    s       = tr_lat;
    tr_pkts = 0;
    tr_lat  = 0;
  endfunction

  function automatic void open_window(int unsigned s, int unsigned e);
    w_start = s;
    w_end   = e;
  endfunction

  function automatic bit in_window(int unsigned t);
    return (t >= w_start) && (t < w_end);
  endfunction

  function automatic void on_create(int len, int unsigned t);
    if (in_window(t)) begin
      off_flits += longint'(len);
      m_pkts++;
      m_left++;
    end
  endfunction

  function automatic void on_arrive(int unsigned t);
    if (in_window(t)) acc_flits++;
  endfunction

  function automatic void on_deliver(int src, int dst, int len, int unsigned t_create, int unsigned t_eject,
                                     int zl, bit byp);
    longint unsigned lat;
    int unsigned     d;
    int              f;
    d        = t_eject - t_create;
    lat      = longint'(d);
    tr_pkts++;
    tr_lat  += lat;
    if (!in_window(t_create)) return;
    lat_sum += lat;
    zl_sum  += longint'(zl);
    if (lat == longint'(zl)) zl_hits++;
    if (lat > lat_max) lat_max = lat;
    if (lat >= longint'(HIST) - 1) hist[HIST-1]++;
    else                           hist[int'(lat)]++;
    m_flits += longint'(len);
    m_left--;
    if (byp) begin
      byp_pkts++;
      byp_flits += longint'(len);
    end
    src_flits[src] += longint'(len);
    f = src * 256 + dst;
    if (flow_cnt.exists(f) != 0) begin
      flow_cnt[f] = flow_cnt[f] + 1;
      flow_sum[f] = flow_sum[f] + lat;
    end else begin
      flow_cnt[f] = 1;
      flow_sum[f] = lat;
    end
  endfunction

  function automatic longint unsigned delivered_pkts();
    return m_pkts - m_left;
  endfunction

  function automatic real lat_avg();
    if (delivered_pkts() == 0) return 0.0;
    return real'(lat_sum) / real'(delivered_pkts());
  endfunction

  function automatic real zl_avg();
    if (delivered_pkts() == 0) return 0.0;
    return real'(zl_sum) / real'(delivered_pkts());
  endfunction

  function automatic real zl_share();
    if (delivered_pkts() == 0) return 0.0;
    return real'(zl_hits) / real'(delivered_pkts());
  endfunction

  function automatic int lat_pct(real q);
    longint unsigned need, cum;
    if (delivered_pkts() == 0) return 0;
    need = longint'(q * real'(delivered_pkts()) + 0.999999);
    if (need < 1) need = 1;
    cum = 0;
    for (int i = 0; i < HIST; i++) begin
      cum += hist[i];
      if (cum >= need) return i;
    end
    return HIST - 1;
  endfunction

  function automatic real window_len();
    return real'(w_end - w_start);
  endfunction

  function automatic real thr_off();
    if (w_end <= w_start) return 0.0;
    return real'(off_flits) / (real'(n_nodes) * window_len());
  endfunction

  function automatic real thr_acc();
    if (w_end <= w_start) return 0.0;
    return real'(acc_flits) / (real'(n_nodes) * window_len());
  endfunction

  function automatic real jain();
    real s, s2, x;
    s  = 0.0;
    s2 = 0.0;
    for (int i = 0; i < n_nodes; i++) begin
      x   = real'(src_flits[i]);
      s  += x;
      s2 += x * x;
    end
    if (s2 == 0.0) return 0.0;
    return (s * s) / (real'(n_nodes) * s2);
  endfunction

  function automatic real lat_flow_max();
    real worst, a;
    worst = 0.0;
    foreach (flow_cnt[f]) begin
      if (flow_cnt[f] >= longint'(FLOW_MIN)) begin
        if (flow_sum.exists(f) != 0) begin
          a = real'(flow_sum[f]) / real'(flow_cnt[f]);
          if (a > worst) worst = a;
        end
      end
    end
    return worst;
  endfunction

  function automatic bit saturated();
    return thr_acc() < 0.95 * thr_off();
  endfunction

  function automatic real byp_pkt();
    if (delivered_pkts() == 0) return 0.0;
    return real'(byp_pkts) / real'(delivered_pkts());
  endfunction

  function automatic real byp_flit();
    if (m_flits == 0) return 0.0;
    return real'(byp_flits) / real'(m_flits);
  endfunction

  function automatic string byp_cols();
    if (byp_pkts == 0) return "0,0";
    return $sformatf("%0.4f,%0.4f", byp_pkt(), byp_flit());
  endfunction

  function automatic string csv_header();
    return {"run_id,design,N,V,pattern,p_data,b_max,t_mode,policy,epoch,rate,seed,",
            "lat_avg,lat_p50,lat_p99,lat_max,thr_off,thr_acc,byp_pkt,byp_flit,",
            "jain,lat_flow_max,stalls,t_stall,pkts,sat,cycles"};
  endfunction

  function automatic string csv_row(string run_id, string dsg, int n, int v, string pat,
                                    real p_data, real rate, longint unsigned seed,
                                    int stalls, int unsigned t_stall, int unsigned cycles,
                                    string b_max_s = "-", string t_mode_s = "-",
                                    string policy_s = "-", string epoch_s = "-");
    return $sformatf("%s,%s,%0d,%0d,%s,%0.4f,%s,%s,%s,%s,%0.4f,%0d,%0.3f,%0d,%0d,%0d,%0.4f,%0.4f,%s,%0.4f,%0.3f,%0d,%0d,%0d,%0d,%0d",
                     run_id, dsg, n, v, pat, p_data, b_max_s, t_mode_s, policy_s, epoch_s, rate, seed,
                     lat_avg(), lat_pct(0.50), lat_pct(0.99), lat_max, thr_off(), thr_acc(), byp_cols(),
                     jain(), lat_flow_max(), stalls, t_stall, delivered_pkts(),
                     saturated(), cycles);
  endfunction

endpackage

// =============================================================================
// ==== tb/common/sched_ref.sv
// =============================================================================
`timescale 1ns/1ps

package sched_ref_pkg;
  import noc_pkg::*;

  typedef struct {
    int sx;
    int sy;
    int dx;
    int dy;
    bit mode;
  } xfer_t;

  typedef xfer_t xfer_q_t[$];

  typedef struct {
    int x;
    int y;
    int p;
  } link_t;

  typedef link_t link_q_t[$];

  typedef struct {
    bit setup;
    int sub;
    int cyc;
    int slot;
  } pos_t;

  function automatic int ref_group(int x, int y, int n);
    int cx;
    cx = x;
    for (int k = y; k > 0; k--) cx = (cx == 0) ? n - 1 : cx - 1;
    return cx;
  endfunction

  function automatic int ref_row_x(int w, int k, int n);
    int cx;
    cx = w;
    for (int r = 0; r < k; r++) cx = (cx == n - 1) ? 0 : cx + 1;
    return cx;
  endfunction

  function automatic int ref_n_slots(int n);
    int c;
    c = 0;
    for (int b = 0; b < n; b++)
      for (int a = 0; a <= b; a++)
        c++;
    return c;
  endfunction

  function automatic void ref_slot(int n, int slot, output int a, output int b);
    int c;
    c = 0;
    a = -1;
    b = -1;
    for (int bb = 0; bb < n; bb++) begin
      for (int aa = 0; aa <= bb; aa++) begin
        if (c == slot) begin
          a = aa;
          b = bb;
        end
        c++;
      end
    end
  endfunction

  function automatic int ref_table(int n, int g, int t);
    int a, b, found, ns;
    found = -1;
    ns    = ref_n_slots(n);
    for (int s = 0; s < ns; s++) begin
      ref_slot(n, s, a, b);
      if ((a == g && b == t) || (a == t && b == g)) found = s;
    end
    return found;
  endfunction

  function automatic xfer_q_t ref_xfers(int n, int slot, int s, bit same_yx); /*verilator no_inline_task*/
    xfer_q_t q;
    xfer_t   f;
    int      a, b, k;
    q = {};
    ref_slot(n, slot, a, b);
    for (int j = 0; j < n; j++) begin
      if (a != b) begin
        k      = (j + n - s) % n;
        f.sx   = ref_row_x(a, j, n);
        f.sy   = j;
        f.dx   = ref_row_x(b, k, n);
        f.dy   = k;
        f.mode = MODE_XY;                       // towards the higher group: X first
        q.push_back(f);
        f.sx   = ref_row_x(b, k, n);
        f.sy   = k;
        f.dx   = ref_row_x(a, j, n);
        f.dy   = j;
        f.mode = MODE_YX;                       // towards the lower group: Y first
        q.push_back(f);
      end else if (s != 0) begin
        k      = (j + s) % n;
        f.sx   = ref_row_x(a, j, n);
        f.sy   = j;
        f.dx   = ref_row_x(a, k, n);
        f.dy   = k;
        f.mode = same_yx ? MODE_YX : MODE_XY;
        q.push_back(f);
      end
    end
    return q;
  endfunction

  function automatic pos_t ref_pos(int n, int t_sub, int s_setup, longint e);
    longint len, w;
    pos_t   p;
    len    = longint'(s_setup) + longint'(n) * longint'(t_sub);
    w      = e % len;
    p.slot = int'((e / len) % longint'(ref_n_slots(n)));
    if (w < longint'(s_setup)) begin
      p.setup = 1'b1;
      p.sub   = 0;
      p.cyc   = int'(w);
    end else begin
      p.setup = 1'b0;
      p.sub   = int'((w - longint'(s_setup)) / longint'(t_sub));
      p.cyc   = int'((w - longint'(s_setup)) % longint'(t_sub));
    end
    return p;
  endfunction

  function automatic link_q_t ref_path(int sx, int sy, int dx, int dy, bit mode); /*verilator no_inline_task*/
    link_q_t q;
    link_t   l;
    int      x, y;
    q = {};
    x = sx;
    y = sy;
    if (mode == MODE_XY) begin
      while (x != dx) begin
        l.x = x; l.y = y; l.p = (dx > x) ? int'(P_E) : int'(P_W);
        q.push_back(l);
        x = (dx > x) ? x + 1 : x - 1;
      end
    end
    while (y != dy) begin
      l.x = x; l.y = y; l.p = (dy > y) ? int'(P_S) : int'(P_N);
      q.push_back(l);
      y = (dy > y) ? y + 1 : y - 1;
    end
    while (x != dx) begin                       // only for YX: X after Y
      l.x = x; l.y = y; l.p = (dx > x) ? int'(P_E) : int'(P_W);
      q.push_back(l);
      x = (dx > x) ? x + 1 : x - 1;
    end
    return q;
  endfunction

  function automatic void ref_link_end(link_t l, output int x, output int y);
    x = l.x;
    y = l.y;
    case (l.p)
      int'(P_N): y = l.y - 1;
      int'(P_E): x = l.x + 1;
      int'(P_S): y = l.y + 1;
      default:   x = l.x - 1;
    endcase
  endfunction

  function automatic int ref_opposite(int p);
    int r;
    case (p)
      int'(P_N): r = int'(P_S);
      int'(P_E): r = int'(P_W);
      int'(P_S): r = int'(P_N);
      default:   r = int'(P_E);
    endcase
    return r;
  endfunction

  function automatic xfer_q_t ref_mesh_xfers(int n, int rg, bit loc, int slot, int s); /*verilator no_inline_task*/
    xfer_q_t q, r;
    xfer_t   f;
    if (!loc) return ref_xfers(n, slot, s, 1'b0);
    q = ref_xfers(rg, slot, s, 1'b0);
    r = {};
    for (int by = 0; by < n; by += rg) begin
      for (int bx = 0; bx < n; bx += rg) begin
        foreach (q[m]) begin
          f      = q[m];
          f.sx   = bx + q[m].sx;
          f.sy   = by + q[m].sy;
          f.dx   = bx + q[m].dx;
          f.dy   = by + q[m].dy;
          r.push_back(f);
        end
      end
    end
    return r;
  endfunction

  typedef struct {
    bit   loc;        // the local timetable runs
    int   k;          // k_L of this frame (0 with one pointer)
    int   lc;         // local slots finished in this frame (0 in its global slot)
    pos_t lp;         // local counter
    pos_t gp;         // global counter
    bit   fstart;     // the first cycle of a frame
  } fpos_t;

  class frame_ref;
    int     n, rg, tl, tg, sl, sg;    // sides, subslot lengths, setup windows
    bit     two;                      // two pointers (rg < n)
    longint ll, lg;                   // slot lengths
    longint sc  [$];
    int     sk  [$];
    longint sel [$];
    longint seg [$];
    int     cur;                      // segment of the last at() (cycles only grow)

    function new(int n_c, int rg_c, int tl_c, int tg_c, int k0);
      n   = n_c;
      rg  = rg_c;
      tl  = tl_c;
      tg  = tg_c;
      sl  = 2 * (rg - 1) + 1;         // Hmax + 1 (D13), counted here, not from sched_pkg
      sg  = 2 * (n - 1) + 1;
      two = (rg < n);
      ll  = longint'(sl) + longint'(rg) * longint'(tl);
      lg  = longint'(sg) + longint'(n) * longint'(tg);
      sc.push_back(0);
      sk.push_back(two ? k0 : 0);
      sel.push_back(0);
      seg.push_back(0);
      cur = 0;
    endfunction

    function longint flen(int k);
      return longint'(k) * ll + lg;
    endfunction

    function int sample(longint s, int k);
      int     j;
      longint i, f, fl, kj, cj, el, eg;
      if (!two) return 0;
      j  = sc.size() - 1;
      cj = sc[j];
      if (cj > s) begin               // the newest segment has not started: replace its plan
        sk[j] = k;
        return 2;
      end
      kj = longint'(sk[j]);
      fl = flen(sk[j]);
      i  = (s - cj) / fl + 1;         // frames of segment j that start at or before s
      f  = cj + i * fl;
      el = sel[j];
      eg = seg[j];
      sc.push_back(f);
      sk.push_back(k);
      sel.push_back(el + i * kj * ll);
      seg.push_back(eg + i * lg);
      return 1;
    endfunction

    function longint last_start();
      return sc[sc.size() - 1];
    endfunction

    function longint next_frame(longint e);
      fpos_t  p;
      longint c;
      c = e;
      p = at(c);
      while (!p.fstart) begin
        c++;
        p = at(c);
      end
      return c;
    endfunction

    function fpos_t at(longint e);
      fpos_t  p;
      longint w, fl, f, r, el, eg, kl, s0, se, sg0;
      int     k, ns;
      ns = sc.size();
      if (cur >= ns) cur = 0;
      s0 = sc[cur];
      if (s0 > e) cur = 0;
      for (int j = 0; j < ns; j++) begin   // forward to the segment that holds e (no call in a loop condition)
        if (cur + 1 >= ns) break;
        s0 = sc[cur + 1];
        if (s0 > e) break;
        cur++;
      end
      k        = sk[cur];
      kl       = longint'(k);
      s0       = sc[cur];
      se       = sel[cur];
      sg0      = seg[cur];
      w        = e - s0;
      p.k      = k;
      p.lc     = 0;
      p.fstart = 1'b0;
      if (!two) begin
        p.loc    = 1'b0;
        el       = 0;
        eg       = e;
        p.fstart = (e % lg == 0);
      end else if (k == 0) begin
        p.loc    = 1'b0;
        el       = se;
        eg       = sg0 + w;
        p.fstart = (w % lg == 0);
      end else begin
        fl       = flen(k);
        f        = w / fl;
        r        = w % fl;
        p.fstart = (r == 0);
        if (r < kl * ll) begin
          p.loc = 1'b1;
          p.lc  = int'(r / ll);
          el    = se + f * kl * ll + r;
          eg    = sg0 + f * lg;
        end else begin
          p.loc = 1'b0;                 // the global slot (lc reads 0 there, as the RTL's)
          el    = se + (f + 1) * kl * ll;
          eg    = sg0 + f * lg + (r - kl * ll);
        end
      end
      p.lp = ref_pos(rg, tl, sl, el);
      p.gp = ref_pos(n, tg, sg, eg);
      return p;
    endfunction
  endclass

  frame_ref the_fr;

  function automatic int ref_pair_turns(int n);
    int ns, np;
    ns = ref_n_slots(n);
    np = n * n * (n * n - 1);
    return np / ns;
  endfunction

  function automatic real ref_alpha(int n, int rg);
    int  pg, pl, nr, d;
    real a, b;
    pg = ref_pair_turns(n);
    pl = ref_pair_turns(rg);
    nr = n / rg;
    d  = pl * nr * nr;
    a  = real'(pg);
    b  = real'(d);
    return a / b;
  endfunction

  function automatic int ref_kmax(int n);
    if (n >= 16) return 47;
    return 15;
  endfunction

  function automatic int ref_bin(longint cl, longint cg);
    longint s, t;
    s = cl + cg;
    if (s == 0) return -1;
    t = 64'sd16 * cl;
    t = t / s;
    return int'(t);
  endfunction

  function automatic int ref_kl(int pol, int n, int rg, int q, int kmin = 1, int kmax = -1);
    real    al, r, u, v, x;
    int     kmx, k, pg, pl, nr, ui, vi;
    longint num, den, t;
    kmx = kmax;
    if (kmx < 0) kmx = ref_kmax(n);
    ui  = 2 * q + 1;
    vi  = 31 - 2 * q;
    if (pol == 1) begin
      al = ref_alpha(n, rg);
      u  = real'(ui);
      v  = real'(vi);
      r  = u / v;
      x  = $sqrt(r);
      x  = al * x;
    end else begin
      pg  = ref_pair_turns(n);
      pl  = ref_pair_turns(rg);
      nr  = n / rg;
      num = longint'(pg);
      t   = longint'(ui);
      num = num * t;
      den = longint'(pl);
      t   = longint'(nr);
      den = den * t * t;
      t   = longint'(vi);
      den = den * t;
      x   = real'(num);
      r   = real'(den);
      x   = x / r;
    end
    x = x + 0.5;
    k = $rtoi(x);
    if (k < kmin) k = kmin;
    if (k > kmx)  k = kmx;
    return k;
  endfunction

  function automatic int ref_next_kl(int pol, bit damp, int n, int rg, longint cl, longint cg, int k_old,
                                     int kmin = 1, int kmax = -1);
    int q, kt, kn, kmx;
    kmx = kmax;
    if (kmx < 0) kmx = ref_kmax(n);
    q   = ref_bin(cl, cg);
    if (q < 0)        kt = k_old;
    else if (q >= 16) kt = kmx;
    else              kt = ref_kl(pol, n, rg, q, kmin, kmx);
    if (kt < kmin) kt = kmin;
    if (kt > kmx)  kt = kmx;
    if (!damp)           kn = kt;
    else if (kt > k_old) kn = (k_old + kt + 1) / 2;
    else                 kn = (k_old + kt) / 2;
    if (kn < kmin) kn = kmin;
    if (kn > kmx)  kn = kmx;
    return kn;
  endfunction

  function automatic int ref_plan_by(int n);
    int nn, l, w;
    nn = n * n;
    l  = 0;
    for (int i = 0; i < 9; i++) begin
      if ((1 << l) < nn) l++;
    end
    w = 14 + l;
    return 4 * n + w + 6;
  endfunction

endpackage

