`timescale 1ns/1ps

package perf_pkg;

  typedef struct {
    longint unsigned turns, used, cxl, lost, bflits, bpkts, dec, acc, rcx, nosh, two;
  } snap_t;

  function automatic string header();
    return "turns,bursts,src_cancels,lost,byp_flits,byp_pkts,decisions,accepted,dst_cancels,noshows,two_waiting";
  endfunction

  function automatic string header_two();
    return "k_mean,k_min,k_max,k_changes,share_L,turn_max_L,turn_max_G,kL_trace";
  endfunction

  function automatic string row_na();
    return "-,-,-,-,-,-,-,-,-,-,-";
  endfunction
  function automatic string row_two_na();
    return "-,-,-,-,-,-,-,-";
  endfunction

  function automatic string row(snap_t a, snap_t b);
    return $sformatf("%0d,%0d,%0d,%0d,%0d,%0d,%0d,%0d,%0d,%0d,%0d",
                     b.turns - a.turns, b.used - a.used, b.cxl - a.cxl, b.lost - a.lost,
                     b.bflits - a.bflits, b.bpkts - a.bpkts, b.dec - a.dec, b.acc - a.acc,
                     b.rcx - a.rcx, b.nosh - a.nosh, b.two - a.two);
  endfunction

endpackage

// =============================================================================
// ==== tb/checkers/ni_checker.sv
// =============================================================================
`timescale 1ns/1ps
// `include "tb_macros.svh": inlined earlier in this bundle

package nchk_pkg;

  /* verilator lint_off UNUSEDSIGNAL */

  localparam int MAXN = 256;            // routers

  class nchk;
    int              nn, bmax, space, ejd, regv;
    int              res   [MAXN];
    longint          arr   [MAXN];      // bypass flits written, cycles before this one
    longint          taken [MAXN];      // bypass flits the core took (sink, sampled this cycle)
    int              wdue  [MAXN][$];   // accepted bursts: cycle their lookahead is due
    bit              arr_now [MAXN];    // a bypass flit is written this cycle
    int              p_res  [MAXN];
    int              p_fill [MAXN];
    int              p_occ  [MAXN];     // flits in the FIFO
    longint unsigned n_dec, n_acc, n_cxl, n_noshow, n_la, n_cmp;
    int              max_fill, max_sum, max_occ, max_reg;

    function new(int nodes, int b_max, int space_c, int ej_depth, int reg_c);
      nn    = nodes;
      bmax  = b_max;
      space = space_c;
      ejd   = ej_depth;
      regv  = reg_c;
      res     = '{default: 0};
      arr     = '{default: 0};
      taken   = '{default: 0};
      arr_now = '{default: 1'b0};
      p_res   = '{default: 0};
      p_fill  = '{default: 0};
      p_occ   = '{default: 0};
      n_dec = 0; n_acc = 0; n_cxl = 0; n_noshow = 0; n_la = 0; n_cmp = 0;
      max_fill = 0; max_sum = 0; max_occ = 0; max_reg = 0;
    endfunction

    function int fill(int r);
      return int'(arr[r] - taken[r]);
    endfunction

    function void compare(int c);
      int f, reg_part;
      for (int r = 0; r < nn; r++) begin
        f        = fill(r);
        reg_part = p_occ[r] - f;
        n_cmp++;
        tb_pkg::n_checks++;
        if (p_res[r] != res[r] || p_fill[r] != f)
          tb_pkg::fail($sformatf("NI R%0d at cycle %0d: reserved %0d, bypass flits in the FIFO %0d; the model says %0d and %0d",
                                 r, c, p_res[r], p_fill[r], res[r], f));
        `TB_CHECK(f >= 0 && res[r] >= 0 && f + res[r] <= space,
                  ("NI R%0d at cycle %0d: bypass flits %0d + reserved %0d, bypass space %0d", r, c, f, res[r], space))
        `TB_CHECK(p_occ[r] <= ejd && reg_part >= 0 && reg_part <= regv,
                  ("NI R%0d at cycle %0d: %0d flits in the FIFO, %0d of them bypass: %0d regular (credits allow %0d), depth %0d",
                   r, c, p_occ[r], f, reg_part, regv, ejd))
        if (f > max_fill)          max_fill = f;
        if (f + res[r] > max_sum)  max_sum  = f + res[r];
        if (p_occ[r] > max_occ)    max_occ  = p_occ[r];
        if (reg_part > max_reg)    max_reg  = reg_part;
      end
    endfunction

    function bit decide(int r, int due_c);
      bit ok;
      n_dec++;
      ok = fill(r) + res[r] + bmax <= space;
      if (ok) begin
        res[r] += bmax;
        wdue[r].push_back(due_c);
        n_acc++;
      end else begin
        n_cxl++;
      end
      return ok;
    endfunction

    function void due(int r, int c, int len);
      int d;
      `TB_CHECK(wdue[r].size() > 0, ("NI R%0d at cycle %0d: a lookahead is due with no burst reserved", r, c))
      if (wdue[r].size() == 0) return;
      d = wdue[r].pop_front();
      `TB_CHECK(d == c, ("NI R%0d: the oldest reservation's lookahead is due at cycle %0d, not %0d", r, d, c))
      if (len == 0) begin
        res[r] -= bmax;
        n_noshow++;
      end else begin
        res[r] -= bmax - len;
        n_la++;
      end
    endfunction

    function void end_cycle(int c);
      for (int r = 0; r < nn; r++) begin
        if (arr_now[r]) begin
          arr[r]++;
          res[r]--;
          `TB_CHECK(res[r] >= 0, ("NI R%0d at cycle %0d: a bypass flit arrived that no reservation covered", r, c))
        end
        arr_now[r] = 1'b0;
      end
    endfunction

    function int waiting();
      int s;
      s = 0;
      for (int r = 0; r < nn; r++) s += wdue[r].size();
      return s;
    endfunction
  endclass

  nchk the_nchk;
  /* verilator lint_on UNUSEDSIGNAL */

endpackage

// =============================================================================
// ==== tb/checkers/router_checker.sv
// =============================================================================
`timescale 1ns/1ps
// `include "tb_macros.svh": inlined earlier in this bundle

package rchk_pkg;
  import noc_pkg::*;
  import sched_pkg::*;
  import sched_ref_pkg::*;

  /* verilator lint_off UNUSEDSIGNAL */

  localparam int W    = 256;          // cycles of expected events kept (ring)
  localparam int NB   = 4096;         // bursts kept (ring)
  localparam int MAXN = 256;          // routers
  localparam int MAXL = 32;           // hops on a path
  localparam int NRES = 13;           // per router: flit links N E S W, la links N E S W, NI, cancel links N E S W

  typedef struct {
    int cyc;
    int kind;
    int res;
    int b;
    int idx;
    int lnk;
    int ext;
  } ev_t;

  typedef struct {
    int cyc;
    int node;
    int len;
  } due_t;

  class rchk;
    int  n, nn, tsub, sset, bmax;
    int  c0;
    bit  started;
    sched_ref_pkg::frame_ref fr;
    int  rg, tl, sl;
    flit_t obs_fl [];
    la_t   obs_la [];
    cx_t   obs_cx [];
    bit    obs_v  [];
    nchk_pkg::nchk nck;
    int    dec_t   [MAXN];
    bit    dec_acc [MAXN];
    due_t  dues [$];
    int    b_src  [NB];
    int    b_dst  [NB];
    int    b_mode [NB];
    int    b_len  [NB];               // hops L
    int    b_t    [NB];
    int    b_n    [NB];               // flits B (-1 until the lookahead is seen)
    int    b_slot [NB];
    int    b_sub  [NB];
    bit    b_loc  [NB];               // a burst of the local timetable
    int    b_pr   [NB][MAXL];         // link i leaves router b_pr[i-1] through port b_pp[i-1]
    int    b_pp   [NB][MAXL];
    ftype_t           b_ft  [NB][16];
    logic [127:0]     b_dat [NB][16];
    bit    b_acc  [NB];               // its destination reserved space
    bit    b_cx   [NB];               // its destination cancelled it
    int    nxt;                       // next burst id
    int    pend [$];                  // bursts whose lookahead is due at t + 2
    ev_t   bucket [W][$];             // expected events by cycle
    longint unsigned n_sub, n_allowed, n_bursts, n_flits, n_pkts, n_multi, n_full, n_ev, n_long;
    longint unsigned n_dec, n_cxd, n_tok, n_cxok;
    longint unsigned n_lsub, n_lallowed, n_lbursts, n_xtail;    // design C: local subslots, ...
    int    lb_reg [MAXN];             // design C: local bursts per region
    int    max_b;

    function new(int mesh_n, int t_sub_c, int s_setup_c, int b_max);
      n     = mesh_n;
      nn    = mesh_n * mesh_n;
      tsub  = t_sub_c;
      sset  = s_setup_c;
      bmax  = b_max;
      obs_fl = new[MAXN * NRES];
      obs_la = new[MAXN * NRES];
      obs_cx = new[MAXN * NRES];
      obs_v  = new[MAXN * NRES];
      nck    = null;
      for (int r = 0; r < MAXN; r++) begin
        dec_t[r]   = -1;
        dec_acc[r] = 1'b0;
      end
      started = 1'b0;
      c0      = 0;
      nxt     = 0;
      n_sub = 0; n_allowed = 0; n_bursts = 0; n_flits = 0; n_pkts = 0; n_multi = 0; n_full = 0;
      n_ev = 0; n_long = 0; max_b = 0;
      n_dec = 0; n_cxd = 0; n_tok = 0; n_cxok = 0;
      n_lsub = 0; n_lallowed = 0; n_lbursts = 0; n_xtail = 0;
      for (int r = 0; r < MAXN; r++) lb_reg[r] = 0;
      fr = null;
      rg = mesh_n;
      tl = t_sub_c;
      sl = s_setup_c;
    endfunction

    function void set_frames(sched_ref_pkg::frame_ref f, int region_n, int t_loc, int s_loc);
      fr = f;
      rg = region_n;
      tl = t_loc;
      sl = s_loc;
    endfunction

    function string res_name(int res);
      int    r, k;
      string s;
      r = res / NRES;
      k = res % NRES;
      if (k < 4)       s = $sformatf("link %s of R%0d", tb_pkg::port_name(3'(k)), r);
      else if (k < 8)  s = $sformatf("lookahead link %s of R%0d", tb_pkg::port_name(3'(k - 4)), r);
      else if (k == 8) s = $sformatf("Local output (NI write) of R%0d", r);
      else             s = $sformatf("cancel link %s of R%0d", tb_pkg::port_name(3'(k - 9)), r);
      return s;
    endfunction

    function string bname(int b);
      string w;
      if (b_loc[b]) w = "local slot";
      else          w = "slot";
      return $sformatf("burst R%0d->R%0d (%s %0d subslot %0d, t=%0d, %0d hops)",
                       b_src[b], b_dst[b], w, b_slot[b], b_sub[b], b_t[b], b_len[b]);
    endfunction

    function void expect_ev(int cyc, int kind, int res, int b, int idx, int lnk, int ext);
      ev_t e;
      e.cyc  = cyc;
      e.kind = kind;
      e.res  = res;
      e.b    = b;
      e.idx  = idx;
      e.lnk  = lnk;
      e.ext  = ext;
      bucket[cyc % W].push_back(e);           // cyc >= 0: an unsigned index (D30)
    endfunction

    function void add_due(int cyc, int node, int len);
      due_t du;
      du.cyc  = cyc;
      du.node = node;
      du.len  = len;
      dues.push_back(du);
    endfunction

    function void decide_all(int d, int t, bit loc, int sn, int k);
      xfer_q_t q;
      link_q_t p, rp;
      int      src, dst, L, bmode;
      bit      acc;
      q = ref_mesh_xfers(n, rg, loc, sn, k);
      foreach (q[m]) begin
        p   = ref_path(q[m].sx, q[m].sy, q[m].dx, q[m].dy, q[m].mode);
        src = q[m].sy * n + q[m].sx;
        dst = q[m].dy * n + q[m].dx;
        L   = p.size();
        acc = 1'b1;
        if (nck != null) acc = nck.decide(dst, t + tc_la(L));
        n_dec++;
        dec_t[src]   = t;
        dec_acc[src] = acc;
        if (!acc) begin
          n_cxd++;
          rp = ref_path(q[m].dx, q[m].dy, q[m].sx, q[m].sy, !q[m].mode);
          `TB_CHECK(rp.size() == L, ("checker: the way back from R%0d to R%0d has %0d hops, the burst %0d", dst, src, rp.size(), L))
          bmode = q[m].mode ? 0 : 1;
          foreach (rp[h])
            expect_ev(d + tc_cancel(h + 1), 3, (rp[h].y * n + rp[h].x) * NRES + 9 + rp[h].p, -1, src, h + 1, bmode);
        end
      end
    endfunction

    function void subslot_start(int t, bit loc, int sn, int k);
      xfer_q_t q;
      link_q_t p;
      int      b;
      q = ref_mesh_xfers(n, rg, loc, sn, k);
      n_sub++;
      if (loc) n_lsub++;
      foreach (q[m]) begin
        p = ref_path(q[m].sx, q[m].sy, q[m].dx, q[m].dy, q[m].mode);
        b = nxt % NB;
        nxt++;
        b_src[b]  = q[m].sy * n + q[m].sx;
        b_dst[b]  = q[m].dy * n + q[m].dx;
        b_mode[b] = int'(q[m].mode);
        b_len[b]  = p.size();
        b_t[b]    = t;
        b_n[b]    = -1;
        b_slot[b] = sn;
        b_sub[b]  = k;
        b_loc[b]  = loc;
        `TB_CHECK(dec_t[b_src[b]] == t, ("checker: %s was never decided (reserve or cancel) one subslot ahead", bname(b)))
        b_acc[b]  = (dec_t[b_src[b]] == t) && dec_acc[b_src[b]];
        b_cx[b]   = (dec_t[b_src[b]] == t) && !dec_acc[b_src[b]];
        foreach (p[h]) begin
          b_pr[b][h] = p[h].y * n + p[h].x;
          b_pp[b][h] = p[h].p;
        end
        pend.push_back(b);
        n_allowed++;
        if (loc) n_lallowed++;
      end
    endfunction

    function void resolve(int b, int c);
      int res, bl, L, te;
      la_t a;
      L   = b_len[b];
      res = b_pr[b][0] * NRES + 4 + b_pp[b][0];
      tb_pkg::n_checks++;
      if (b_cx[b]) begin                       // cancelled: the source must send nothing
        b_n[b] = 0;
        if (obs_v[res]) begin
          tb_pkg::fail($sformatf("%s: its destination cancelled it, but the source sent a burst of %0d flits",
                                 bname(b), obs_la[res].len));
          obs_v[res] = 1'b0;
        end else begin
          n_cxok++;
        end
        return;
      end
      if (!obs_v[res]) begin
        b_n[b] = 0;
        if (b_acc[b]) add_due(b_t[b] + tc_la(L), b_dst[b], 0);   // no-show: released at t + 2L
        return;
      end
      a         = obs_la[res];
      obs_v[res] = 1'b0;                       // consumed
      bl        = int'(a.len);
      `TB_CHECK(int'(a.dst) == b_dst[b] && int'(a.mode) == b_mode[b] && a.vc == '0 && bl >= 1 && bl <= bmax,
                ("%s: lookahead on its first link says R%0d, mode %0d, vc %0d, %0d flits (B_MAX %0d)",
                 bname(b), a.dst, a.mode, a.vc, bl, bmax))
      if (bl < 1 || bl > bmax) bl = (bl < 1) ? 1 : bmax;
      b_n[b] = bl;
      n_bursts++;
      n_flits += longint'(bl);
      if (bl == bmax) n_full++;
      if (bl > max_b) max_b = bl;
      te = b_loc[b] ? tl : tsub;
      if (2 * L + 3 + bl - 1 >= te) n_long++;     // last flit lands in a later subslot (TIGHT)
      if (b_loc[b]) begin
        n_lbursts++;
        lb_reg[((b_src[b] / n) / rg) * (n / rg) + (b_src[b] % n) / rg]++;
      end
      if (b_acc[b]) add_due(b_t[b] + tc_la(L), b_dst[b], bl);
      for (int i = 2; i <= L; i++)
        expect_ev(b_t[b] + tc_la(i), 1, b_pr[b][i - 1] * NRES + 4 + b_pp[b][i - 1], b, i, i, 0);
      for (int i = 1; i <= L; i++)
        for (int j = 0; j < bl; j++)
          expect_ev(b_t[b] + tc_link(i, j), 0, b_pr[b][i - 1] * NRES + b_pp[b][i - 1], b, j, i, 0);
      for (int j = 0; j < bl; j++)
        expect_ev(b_t[b] + tc_eject(L, j), 2, b_dst[b] * NRES + 8, b, j, L + 1, 0);
      if (c != b_t[b] + tc_la(1))
        tb_pkg::fail($sformatf("checker: %s resolved at cycle %0d", bname(b), c));
    endfunction

    function void burst_integrity(int b);
      int    j, k, len, np;
      head_t h;
      j  = 0;
      np = 0;
      while (j < b_n[b]) begin
        h   = head_t'(b_dat[b][j]);
        len = int'(h.len);
        `TB_CHECK(is_head(b_ft[b][j]) && (len == 1 || len == MAX_PKT_FLITS) && int'(h.dst) == b_dst[b] && j + len <= b_n[b],
                  ("%s: flit %0d should start a whole packet for R%0d: type %b, length %0d, destination %0d, burst %0d flits",
                   bname(b), j, b_dst[b], b_ft[b][j], len, h.dst, b_n[b]))
        if (!(is_head(b_ft[b][j]) && (len == 1 || len == MAX_PKT_FLITS) && j + len <= b_n[b])) return;
        for (k = 1; k < len; k++)
          `TB_CHECK(!is_head(b_ft[b][j + k]) && is_tail(b_ft[b][j + k]) == (k == len - 1),
                    ("%s: flit %0d (packet flit %0d of %0d) has type %b", bname(b), j + k, k, len, b_ft[b][j + k]))
        `TB_CHECK(len == 1 ? b_ft[b][j] == FT_SINGLE : b_ft[b][j] == FT_HEAD,
                  ("%s: packet at flit %0d of length %0d starts with type %b", bname(b), j, len, b_ft[b][j]))
        j  = j + len;
        np++;
      end
      n_pkts += longint'(np);
      if (np > 1) n_multi++;
    endfunction

    function void step(int c);
      pos_t  pz;
      sched_ref_pkg::fpos_t fp;
      bit    loc;
      int    e, b, nleft, r, otgt, omode, tn, tt, ts;
      ev_t   ev;
      string what;
      due_t  du;
      if (!started) return;
      if (nck != null) begin
        nck.compare(c);
        for (int i = 0; i < nn; i++) nck.arr_now[i] = obs_v[i * NRES + 8];
      end
      e  = c - c0;
      if (fr == null) begin
        pz  = ref_pos(n, tsub, sset, longint'(e));
        loc = 1'b0;
      end else begin
        fp  = fr.at(longint'(e));
        loc = fp.loc;
        if (loc) pz = fp.lp;
        else     pz = fp.gp;
      end
      if (loc) begin
        tn = rg;
        tt = tl;
        ts = sl;
      end else begin
        tn = n;
        tt = tsub;
        ts = sset;
      end
      if (!pz.setup && pz.cyc == 0) subslot_start(c, loc, pz.slot, pz.sub);
      if (pz.cyc == 0) begin
        if (pz.setup)              decide_all(c, c + ts, loc, pz.slot, 0);
        else if (pz.sub < tn - 1)  decide_all(c, c + tt, loc, pz.slot, pz.sub + 1);
      end
      nleft = pend.size();
      for (int k = 0; k < nleft; k++) begin
        b = pend.pop_front();
        if (b_t[b] + tc_la(1) == c) resolve(b, c);
        else                        pend.push_back(b);
      end
      nleft = bucket[c % W].size();
      for (int k = 0; k < nleft; k++) begin
        ev = bucket[c % W].pop_front();
        if (ev.cyc != c) begin
          bucket[c % W].push_back(ev);     // a later lap of the ring
          continue;
        end
        b = ev.b;
        tb_pkg::n_checks++;
        if (ev.kind == 3) begin                // a cancel token
          if (!obs_v[ev.res]) begin
            tb_pkg::fail($sformatf("cancel token for R%0d expected on %s at cycle %0d (reverse link %0d), not there",
                                   ev.idx, res_name(ev.res), c, ev.lnk));
            continue;
          end
          obs_v[ev.res] = 1'b0;
          n_tok++;
          otgt  = int'(obs_cx[ev.res].tgt);
          omode = int'(obs_cx[ev.res].mode);
          `TB_CHECK(otgt == ev.idx && omode == ev.ext,
                    ("cancel token on %s at cycle %0d is for R%0d mode %0d, expected R%0d mode %0d", res_name(ev.res), c,
                     otgt, omode, ev.idx, ev.ext))
          continue;
        end
        n_ev++;
        if (!obs_v[ev.res]) begin
          if (ev.kind == 1) what = $sformatf("lookahead (link %0d)", ev.idx);
          else              what = $sformatf("flit %0d (link %0d)", ev.idx, ev.lnk);
          tb_pkg::fail($sformatf("%s: %s expected on %s at cycle %0d (t+%0d), not there",
                                 bname(b), what, res_name(ev.res), c, c - b_t[b]));
          continue;
        end
        obs_v[ev.res] = 1'b0;
        if (ev.kind == 1) begin
          `TB_CHECK(int'(obs_la[ev.res].dst) == b_dst[b] && int'(obs_la[ev.res].mode) == b_mode[b] &&
                    int'(obs_la[ev.res].len) == b_n[b] && obs_la[ev.res].vc == '0,
                    ("%s: lookahead on %s says R%0d mode %0d %0d flits", bname(b), res_name(ev.res),
                     obs_la[ev.res].dst, obs_la[ev.res].mode, obs_la[ev.res].len))
        end else begin
          if (ev.kind == 2 && ev.idx == b_n[b] - 1 && fr != null) begin
            fp = fr.at(longint'(e));
            if (fp.loc != b_loc[b]) n_xtail++;
          end
          `TB_CHECK(obs_fl[ev.res].vc == '0, ("%s: flit %0d on %s has vc %0d", bname(b), ev.idx, res_name(ev.res), obs_fl[ev.res].vc))
          if (ev.kind == 0 && ev.lnk == 1) begin
            b_ft[b][ev.idx]  = obs_fl[ev.res].ftype;
            b_dat[b][ev.idx] = obs_fl[ev.res].data;
            if (ev.idx == b_n[b] - 1) burst_integrity(b);
          end else begin
            `TB_CHECK(obs_fl[ev.res].ftype == b_ft[b][ev.idx] && obs_fl[ev.res].data == b_dat[b][ev.idx],
                      ("%s: flit %0d changed on %s", bname(b), ev.idx, res_name(ev.res)))
          end
        end
      end
      for (int i = 0; i < nn * NRES; i++) begin
        if (obs_v[i]) begin
          r = i % NRES;
          tb_pkg::n_checks++;
          if (r >= 4 && r < 8)
            tb_pkg::fail($sformatf("unexpected lookahead on %s at cycle %0d: R%0d mode %0d %0d flits",
                                   res_name(i), c, obs_la[i].dst, obs_la[i].mode, obs_la[i].len));
          else if (r >= 9)
            tb_pkg::fail($sformatf("unexpected cancel token on %s at cycle %0d: for R%0d mode %0d",
                                   res_name(i), c, obs_cx[i].tgt, obs_cx[i].mode));
          else
            tb_pkg::fail($sformatf("unexpected bypass flit on %s at cycle %0d (type %b)", res_name(i), c, obs_fl[i].ftype));
          obs_v[i] = 1'b0;
        end
      end
      if (nck != null) begin
        nleft = dues.size();
        for (int k = 0; k < nleft; k++) begin
          du = dues.pop_front();
          if (du.cyc == c)     nck.due(du.node, c, du.len);
          else if (du.cyc > c) dues.push_back(du);
          else                 tb_pkg::fail($sformatf("checker: lookahead of R%0d due at cycle %0d missed", du.node, du.cyc));
        end
        nck.end_cycle(c);
      end
    endfunction

    function int burst_len(int src, int t);
      int r;
      r = -1;
      for (int k = 0; k < NB; k++) begin
        if (b_src[k] == src && b_t[k] == t && k < nxt) r = b_n[k];
      end
      return r;
    endfunction

    function int burst_pkts(int src, int t, output int psrc [16], output int pseq [16], output int plen [16]);
      int    j, np, len;
      head_t h;
      np = 0;
      for (int i = 0; i < 16; i++) begin
        psrc[i] = -1;
        pseq[i] = -1;
        plen[i] = 0;
      end
      for (int k = 0; k < NB; k++) begin
        if (k < nxt && b_src[k] == src && b_t[k] == t && b_n[k] > 0) begin
          j = 0;
          while (j < b_n[k] && np < 16) begin
            h   = head_t'(b_dat[k][j]);
            len = int'(h.len);
            if (len < 1) break;               // burst_integrity has reported it
            psrc[np] = int'(h.src);
            pseq[np] = int'(h.seq);
            plen[np] = len;
            np++;
            j = j + len;
          end
        end
      end
      return np;
    endfunction

    function bit idle();
      int s;
      s = 0;
      for (int k = 0; k < W; k++) s += bucket[k].size();
      return (s == 0);
    endfunction
  endclass

  rchk the_chk;
  /* verilator lint_on UNUSEDSIGNAL */

endpackage

// =============================================================================
// ==== tb/common/sched_monitor.sv
// =============================================================================
`timescale 1ns/1ps
// `include "tb_macros.svh": inlined earlier in this bundle

package smon_pkg;
  import noc_pkg::*;
  import sched_ref_pkg::*;

  /* verilator lint_off UNUSEDSIGNAL */

  localparam int MAXN = 256;            // routers

  class smon;
    int  n, nn, rg, c0;
    bit  started;
    frame_ref fr;
    bit  tx_go   [MAXN];
    int  tx_dst  [MAXN];
    bit  tx_mode [MAXN];
    bit  dec     [MAXN];
    bit  dec_s0  [MAXN];
    bit  dec_loc [MAXN];
    int  dec_src [MAXN];
    bit  dec_mode[MAXN];
    int  dec_hops[MAXN];
    int  last_t  [];
    int  max_gap [];
    int  min_gap [];
    int  cnt_l   [];
    int  cnt_g   [];
    bit  same_r  [];                    // both routers in one region
    longint unsigned n_lturns, n_gturns, n_lrounds, n_grounds, n_lsub, n_gsub, n_ldec, n_gdec;
    int  turns_reg [MAXN];              // local turns per region
    bit  seen_l, seen_g;                // a round has started (the next round start ends it)

    function new(int mesh_n, int region_n, frame_ref f);
      fpos_t fp0;
      n   = mesh_n;
      nn  = mesh_n * mesh_n;
      rg  = region_n;
      fr  = f;
      c0  = 0;
      started = 1'b0;
      last_t  = new[nn * nn];
      max_gap = new[nn * nn];
      min_gap = new[nn * nn];
      cnt_l   = new[nn * nn];
      cnt_g   = new[nn * nn];
      same_r  = new[nn * nn];
      for (int s = 0; s < nn; s++) begin
        for (int d = 0; d < nn; d++) begin
          last_t[s * nn + d] = -1;
          cnt_l[s * nn + d]  = 0;
          cnt_g[s * nn + d]  = 0;
          same_r[s * nn + d] = (reg_of(s) == reg_of(d)) && (s != d);
        end
      end
      clear_gaps();
      for (int r = 0; r < MAXN; r++) begin
        turns_reg[r] = 0;
        tx_go[r]     = 1'b0;
        tx_dst[r]    = 0;
        tx_mode[r]   = 1'b0;
        dec[r]       = 1'b0;
        dec_s0[r]    = 1'b0;
        dec_loc[r]   = 1'b0;
        dec_src[r]   = 0;
        dec_mode[r]  = 1'b0;
        dec_hops[r]  = 0;
      end
      n_lturns = 0; n_gturns = 0; n_lrounds = 0; n_grounds = 0;
      n_lsub = 0; n_gsub = 0; n_ldec = 0; n_gdec = 0;
      fp0    = f.at(0);
      seen_l = fp0.loc;
      seen_g = !fp0.loc;
    endfunction

    function int reg_of(int r);
      return ((r / n) / rg) * (n / rg) + (r % n) / rg;
    endfunction

    function int hops(int a, int b);
      int dx, dy;
      dx = (a % n) - (b % n);
      dy = (a / n) - (b / n);
      if (dx < 0) dx = -dx;
      if (dy < 0) dy = -dy;
      return dx + dy;
    endfunction

    function void clear_gaps();
      for (int i = 0; i < nn * nn; i++) begin
        max_gap[i] = -1;
        min_gap[i] = -1;
        last_t[i]  = -1;
      end
    endfunction

    function void turn(int src, int dst, bit loc, int c);
      int k, g, rs;
      k  = src * nn + dst;
      rs = reg_of(src);
      if (last_t[k] >= 0) begin
        g = c - last_t[k];
        if (max_gap[k] < 0 || g > max_gap[k]) max_gap[k] = g;
        if (min_gap[k] < 0 || g < min_gap[k]) min_gap[k] = g;
      end
      last_t[k] = c;
      if (loc) begin
        cnt_l[k]++;
        n_lturns++;
        turns_reg[rs]++;
        `TB_CHECK(rs == reg_of(dst),
                  ("local turn at cycle %0d: R%0d (region %0d) sends to R%0d in region %0d", c, src, rs, dst, reg_of(dst)))
      end else begin
        cnt_g[k]++;
        n_gturns++;
      end
    endfunction

    function void round_end(bit loc, int c);
      int  bad, fs, fd, fcnt, want, k;
      bad  = 0;
      fs   = -1;
      fd   = -1;
      fcnt = 0;
      for (int s = 0; s < nn; s++) begin
        for (int d = 0; d < nn; d++) begin
          if (s == d) continue;
          k = s * nn + d;
          if (loc) want = same_r[k] ? 1 : 0;
          else     want = 1;
          if ((loc ? cnt_l[k] : cnt_g[k]) != want) begin
            if (bad == 0) begin
              fs   = s;
              fd   = d;
              fcnt = loc ? cnt_l[k] : cnt_g[k];
            end
            bad++;
          end
          if (loc) cnt_l[k] = 0;
          else     cnt_g[k] = 0;
        end
      end
      if (loc) begin
        `TB_CHECK(bad == 0, ("local round ending at cycle %0d: %0d ordered pairs without exactly one local turn per pair inside a region (none outside); first R%0d -> R%0d had %0d",
                             c, bad, fs, fd, fcnt))
        n_lrounds++;
      end else begin
        `TB_CHECK(bad == 0, ("global round ending at cycle %0d: %0d ordered pairs without exactly one global turn; first R%0d -> R%0d had %0d",
                             c, bad, fs, fd, fcnt))
        n_grounds++;
      end
    endfunction

    function void step(int c);
      fpos_t   fp;
      pos_t    pz;
      bit      loc;
      int      e, tn, sub2, src, dst, nbad;
      xfer_q_t q;
      bit      want  [MAXN];
      int      w_dst [MAXN];
      bit      w_md  [MAXN];
      string   ph;
      if (!started) return;
      e   = c - c0;
      fp  = fr.at(longint'(e));
      loc = fp.loc;
      if (loc) begin
        pz = fp.lp;
        tn = rg;
        ph = "local";
      end else begin
        pz = fp.gp;
        tn = n;
        ph = "global";
      end
      if (pz.setup && pz.cyc == 0 && pz.slot == 0) begin
        if (loc) begin
          if (seen_l) round_end(1'b1, c);
          seen_l = 1'b1;
        end else begin
          if (seen_g) round_end(1'b0, c);
          seen_g = 1'b1;
        end
      end
      if (!pz.setup && pz.cyc == 0) begin
        q = ref_mesh_xfers(n, rg, loc, pz.slot, pz.sub);
        for (int r = 0; r < nn; r++) want[r] = 1'b0;
        foreach (q[m]) begin
          src        = q[m].sy * n + q[m].sx;
          want[src]  = 1'b1;
          w_dst[src] = q[m].dy * n + q[m].dx;
          w_md[src]  = q[m].mode;
        end
        if (loc) n_lsub++;
        else     n_gsub++;
        for (int r = 0; r < nn; r++) begin
          if (want[r]) begin
            `TB_CHECK(tx_go[r] && tx_dst[r] == w_dst[r] && tx_mode[r] == w_md[r],
                      ("cycle %0d (%s slot %0d subslot %0d): R%0d should send to R%0d by %s; tile gives turn %0d to R%0d mode %0d",
                       c, ph, pz.slot, pz.sub, r, w_dst[r], w_md[r] ? "YX" : "XY",
                       tx_go[r], tx_dst[r], tx_mode[r]))
            if (tx_go[r]) turn(r, tx_dst[r], loc, c);
          end else begin
            `TB_CHECK(!tx_go[r], ("cycle %0d (%s slot %0d subslot %0d): R%0d has no partner, the tile gives it a turn to R%0d",
                                  c, ph, pz.slot, pz.sub, r, tx_dst[r]))
          end
        end
      end else begin
        nbad = 0;
        src  = -1;
        for (int r = 0; r < nn; r++) begin
          if (tx_go[r]) begin
            if (nbad == 0) src = r;
            nbad++;
          end
        end
        `TB_CHECK(nbad == 0, ("cycle %0d is not the start of a subslot, but %0d tiles give a turn (first R%0d)", c, nbad, src))
      end
      if (pz.cyc == 0 && (pz.setup || pz.sub < tn - 1)) begin
        sub2 = pz.setup ? 0 : pz.sub + 1;
        q    = ref_mesh_xfers(n, rg, loc, pz.slot, sub2);
        for (int r = 0; r < nn; r++) want[r] = 1'b0;
        foreach (q[m]) begin
          dst        = q[m].dy * n + q[m].dx;
          want[dst]  = 1'b1;
          w_dst[dst] = q[m].sy * n + q[m].sx;     // here: the source
          w_md[dst]  = q[m].mode;
        end
        if (loc) n_ldec++;
        else     n_gdec++;
        for (int r = 0; r < nn; r++) begin
          if (want[r]) begin
            `TB_CHECK(dec[r] && dec_src[r] == w_dst[r] && dec_mode[r] == w_md[r] && dec_hops[r] == hops(r, w_dst[r]) &&
                      dec_s0[r] == (sub2 == 0) && dec_loc[r] == loc,
                      ("cycle %0d (%s slot %0d, deciding subslot %0d): R%0d should decide for R%0d, mode %0d, %0d hops; tile says dec %0d from R%0d mode %0d %0d hops s0 %0d local %0d",
                       c, ph, pz.slot, sub2, r, w_dst[r], w_md[r], hops(r, w_dst[r]),
                       dec[r], dec_src[r], dec_mode[r], dec_hops[r], dec_s0[r], dec_loc[r]))
          end else begin
            `TB_CHECK(!dec[r], ("cycle %0d (%s slot %0d, deciding subslot %0d): R%0d has no sender, the tile decides for R%0d",
                                c, ph, pz.slot, sub2, r, dec_src[r]))
          end
        end
      end else begin
        nbad = 0;
        src  = -1;
        for (int r = 0; r < nn; r++) begin
          if (dec[r]) begin
            if (nbad == 0) src = r;
            nbad++;
          end
        end
        `TB_CHECK(nbad == 0, ("cycle %0d is no decision cycle, but %0d tiles decide (first R%0d)", c, nbad, src))
      end
    endfunction

    function void gaps(bit same, output int gmax, output int gmin, output int npairs);
      gmax   = -1;
      gmin   = -1;
      npairs = 0;
      for (int s = 0; s < nn; s++) begin
        for (int d = 0; d < nn; d++) begin
          if (s == d || same_r[s * nn + d] != same || max_gap[s * nn + d] < 0) continue;
          npairs++;
          if (max_gap[s * nn + d] > gmax) gmax = max_gap[s * nn + d];
          if (gmin < 0 || min_gap[s * nn + d] < gmin) gmin = min_gap[s * nn + d];
        end
      end
    endfunction
  endclass

  smon the_smon;
  /* verilator lint_on UNUSEDSIGNAL */

endpackage

// =============================================================================
// ==== tb/checkers/mesh_checker.sv
// =============================================================================
`timescale 1ns/1ps
// `include "tb_macros.svh": inlined earlier in this bundle

package mchk_pkg;
  import noc_pkg::*;
  import sched_pkg::*;
  import sched_ref_pkg::*;

  /* verilator lint_off UNUSEDSIGNAL */

  localparam int MAXN = 256;            // routers

  class mchk;
    int      n, nn, rg, tl, tg, c0;
    bit      started, two;
    frame_ref fr;
    longint  ll, lg;                    // slot lengths
    seq_st_t st     [MAXN];
    bit      fl_v   [MAXN * 4];         // bypass flit on output link r * 4 + p
    bit      la_v   [MAXN * 4];         // lookahead on output link
    int      la_len [MAXN * 4];
    bit      cx_v   [MAXN * 4];         // cancel token on output link
    bit      ej_v   [MAXN];             // bypass flit written into the NI
    bit      lal_v  [MAXN];             // lookahead for the NI
    int      lal_len[MAXN];
    seq_st_t prev;
    bit      have_prev;
    longint unsigned lk_m [MAXN * 4];
    longint unsigned ni_m [MAXN];
    int      lk_beg [MAXN * 4];         // the latest announcement, for messages
    int      lk_end [MAXN * 4];
    int      ni_beg [MAXN];
    int      ni_end [MAXN];
    bit      xreg  [MAXN * 4];         // the link crosses a region boundary
    int      f_start, f_k, f_lslot, f_gslot, f_lends;   // the current frame
    longint unsigned n_frames, n_k_changes, n_lg, n_gl, n_xflits, n_ann, n_nian, n_contain;

    function new(int mesh_n, int region_n, int t_loc, int t_glb, frame_ref f);
      int x, y, s_l, s_g;
      n   = mesh_n;
      nn  = mesh_n * mesh_n;
      rg  = region_n;
      tl  = t_loc;
      tg  = t_glb;
      fr  = f;
      two = (region_n < mesh_n);
      s_l = 2 * (rg - 1) + 1;             // setup windows, Hmax + 1 (D13)
      s_g = 2 * (n - 1) + 1;
      ll  = longint'(s_l) + longint'(rg) * longint'(tl);
      lg  = longint'(s_g) + longint'(n) * longint'(tg);
      c0  = 0;
      started   = 1'b0;
      have_prev = 1'b0;
      for (int r = 0; r < nn; r++) begin
        x = r % n;
        y = r / n;
        xreg[r * 4 + int'(P_N)] = (y > 0) && (y % rg == 0);
        xreg[r * 4 + int'(P_E)] = (x < n - 1) && ((x + 1) % rg == 0);
        xreg[r * 4 + int'(P_S)] = (y < n - 1) && ((y + 1) % rg == 0);
        xreg[r * 4 + int'(P_W)] = (x > 0) && (x % rg == 0);
        for (int p = 0; p < 4; p++) begin
          lk_m  [r * 4 + p] = '0;
          lk_beg[r * 4 + p] = -1;
          lk_end[r * 4 + p] = -2;
        end
        ni_m  [r] = '0;
        ni_beg[r] = -1;
        ni_end[r] = -2;
        st[r]      = '0;
        ej_v[r]    = 1'b0;
        lal_v[r]   = 1'b0;
        lal_len[r] = 0;
        for (int p = 0; p < 4; p++) begin
          fl_v[r * 4 + p]   = 1'b0;
          la_v[r * 4 + p]   = 1'b0;
          la_len[r * 4 + p] = 0;
          cx_v[r * 4 + p]   = 1'b0;
        end
      end
      f_start = 0;
      f_k     = -1;
      f_lends = 0;
      n_frames = 0; n_k_changes = 0; n_lg = 0; n_gl = 0; n_xflits = 0; n_ann = 0; n_nian = 0; n_contain = 0;
    endfunction

    function string st_str(seq_st_t s);
      return $sformatf("phase %0d k_L %0d done %0d | local %0d/%0d/%0d slot %0d | global %0d/%0d/%0d slot %0d",
                       s.loc, s.kl, s.lc, s.l_setup, s.l_sub, s.l_cyc, s.l_slot, s.g_setup, s.g_sub, s.g_cyc, s.g_slot);
    endfunction

    function seq_st_t ref_st(longint e);
      fpos_t   p;
      seq_st_t s;
      p = fr.at(e);
      s = '0;
      s.loc = p.loc;
      s.kl  = kl_t'(p.k);
      s.lc  = kl_t'(p.lc);
      if (two) begin
        s.l_setup = p.lp.setup;
        s.l_sub   = sub_t'(p.lp.sub);
        s.l_cyc   = TCYC_W'(p.lp.cyc);
        s.l_slot  = slot_t'(p.lp.slot);
      end
      s.g_setup = p.gp.setup;
      s.g_sub   = sub_t'(p.gp.sub);
      s.g_cyc   = TCYC_W'(p.gp.cyc);
      s.g_slot  = slot_t'(p.gp.slot);
      return s;
    endfunction

    function bit slot_last(seq_st_t s, bit loc);
      if (loc) return !s.l_setup && int'(s.l_sub) == rg - 1 && int'(s.l_cyc) == tl - 1;
      return !s.g_setup && int'(s.g_sub) == n - 1 && int'(s.g_cyc) == tg - 1;
    endfunction

    function void step(int c);
      seq_st_t s0, x;
      int      nbad, fb, pb, rb, e, fl_bad, ni_bad, ann_bad, k, flc;
      bit      ok, fstart, in_win;
      longint unsigned nm;
      string   why, fs;
      if (!started) return;
      e  = c - c0;
      s0 = st[0];
      nbad = 0;
      fb   = -1;
      for (int r = 1; r < nn; r++) begin
        if (st[r] != s0) begin
          if (nbad == 0) fb = r;
          nbad++;
        end
      end
      fs = "-";
      if (fb >= 0) fs = st_str(st[fb]);
      `TB_CHECK(nbad == 0, ("cycle %0d: %0d tiles out of step with R0; R%0d: %s; R0: %s", c, nbad, fb, fs, st_str(s0)))
      x = ref_st(longint'(e));
      `TB_CHECK(s0 == x, ("cycle %0d: the sequencers are at %s; the frame reference says %s", c, st_str(s0), st_str(x)))
      fstart = (e == 0);
      if (have_prev) begin
        ok  = 1'b1;
        why = "";
        if (s0.loc != prev.loc) begin
          if (!slot_last(prev, prev.loc)) begin
            ok  = 1'b0;
            why = "the phase changed inside a slot";
          end else if (s0.loc ? !(s0.l_setup && s0.l_cyc == '0) : !(s0.g_setup && s0.g_cyc == '0)) begin
            ok  = 1'b0;
            why = "the other timetable did not resume at a setup window";
          end
          if (prev.loc) n_lg++;
          else          n_gl++;
        end
        if (two && prev.loc && s0.loc && (s0.g_setup != prev.g_setup || s0.g_sub != prev.g_sub ||
                                          s0.g_cyc != prev.g_cyc || s0.g_slot != prev.g_slot)) begin
          ok  = 1'b0;
          why = "the global counter moved in the local phase";
        end
        if (two && !prev.loc && !s0.loc && (s0.l_setup != prev.l_setup || s0.l_sub != prev.l_sub ||
                                            s0.l_cyc != prev.l_cyc || s0.l_slot != prev.l_slot)) begin
          ok  = 1'b0;
          why = "the local counter moved in the global phase";
        end
        fstart = !prev.loc && slot_last(prev, 1'b0);       // a global slot just ended
        if (s0.kl != prev.kl) begin
          n_k_changes++;
          if (!fstart) begin
            ok  = 1'b0;
            why = "k_L changed outside a frame start";
          end
        end
        if (two && fstart && (s0.lc != '0 || s0.loc != (s0.kl != '0))) begin
          ok  = 1'b0;
          why = "a frame started with local slots done, or in the wrong phase";
        end
        `TB_CHECK(ok, ("cycle %0d: %s; before: %s; now: %s", c, why, st_str(prev), st_str(s0)))
        if (prev.loc && slot_last(prev, 1'b1)) f_lends++;
      end
      flc = e - f_start;                  // cycles since the frame started
      if (fstart) begin
        if (f_k >= 0) begin
          k = f_k;
          `TB_CHECK(longint'(flc) == longint'(k) * ll + lg && f_lends == (two ? k : 0) &&
                    int'(s0.g_slot) == (f_gslot + 1) % n_slots(n) &&
                    (!two || int'(s0.l_slot) == (f_lslot + k) % n_slots(rg)),
                    ("cycle %0d: the frame from cycle %0d lasted %0d cycles with %0d local slots (k_L %0d: %0d cycles); global slot %0d -> %0d, local slot %0d -> %0d",
                     c, f_start + c0, flc, f_lends, k, longint'(k) * ll + lg, f_gslot, s0.g_slot, f_lslot, s0.l_slot))
          n_frames++;
        end
        f_start = e;
        f_k     = int'(s0.kl);
        f_lslot = int'(s0.l_slot);
        f_gslot = int'(s0.g_slot);
        f_lends = 0;
      end
      flc = e - f_start;
      if (longint'(flc) > 63 * ll + lg)
        $fatal(1, "mesh_checker: no frame has started since cycle %0d (now %0d): the timetable is stuck", f_start + c0, c);
      if (two && s0.loc && !s0.l_setup) begin
        nbad = 0;
        fb   = -1;
        for (int i = 0; i < nn * 4; i++) begin
          if (xreg[i] && (fl_v[i] || la_v[i] || cx_v[i])) begin
            if (nbad == 0) fb = i;
            nbad++;
          end
        end
        if (fb < 0) fb = 0;
        pb = fb % 4;
        rb = fb / 4;
        `TB_CHECK(nbad == 0, ("cycle %0d (local slot %0d): %0d region-crossing links carry bypass traffic; first: link %s of R%0d (flit %0d lookahead %0d token %0d)",
                              c, s0.l_slot, nbad, tb_pkg::port_name(3'(pb)), rb, fl_v[fb], la_v[fb], cx_v[fb]))
        n_contain++;
      end else if (two && !s0.loc) begin
        for (int i = 0; i < nn * 4; i++) if (xreg[i] && fl_v[i]) n_xflits++;
      end
      ann_bad = 0;
      for (int i = 0; i < nn * 4; i++) begin
        lk_m[i] = lk_m[i] >> 1;                       // bit 0: this cycle
        if (la_v[i]) begin
          nm = ((64'd1 << la_len[i]) - 64'd1) << 1;   // cycles c+1 .. c+B
          if ((lk_m[i] & nm) != '0) ann_bad++;        // overlaps a burst announced before
          lk_m[i]   = lk_m[i] | nm;
          lk_beg[i] = c + 1;
          lk_end[i] = c + la_len[i];
          n_ann++;
        end
      end
      for (int r = 0; r < nn; r++) begin
        ni_m[r] = ni_m[r] >> 1;
        if (lal_v[r]) begin
          nm = ((64'd1 << lal_len[r]) - 64'd1) << 3;  // cycles c+3 .. c+2+B
          if ((ni_m[r] & nm) != '0) ann_bad++;
          ni_m[r]   = ni_m[r] | nm;
          ni_beg[r] = c + 3;
          ni_end[r] = c + 2 + lal_len[r];
          n_nian++;
        end
      end
      `TB_CHECK(ann_bad == 0, ("cycle %0d: %0d lookaheads announce flits on a link or an NI that another burst holds then", c, ann_bad))
      fl_bad = 0;
      fb     = -1;
      for (int i = 0; i < nn * 4; i++) begin
        in_win = lk_m[i][0];
        if (fl_v[i] != in_win) begin
          if (fl_bad == 0) fb = i;
          fl_bad++;
        end
      end
      if (fb < 0) fb = 0;
      pb = fb % 4;
      rb = fb / 4;
      `TB_CHECK(fl_bad == 0, ("cycle %0d: %0d links where bypass flits and lookaheads disagree; first: link %s of R%0d, flit %0d, latest announcement cycles %0d..%0d",
                              c, fl_bad, tb_pkg::port_name(3'(pb)), rb, fl_v[fb], lk_beg[fb], lk_end[fb]))
      ni_bad = 0;
      fb     = -1;
      for (int r = 0; r < nn; r++) begin
        in_win = ni_m[r][0];
        if (ej_v[r] != in_win) begin
          if (ni_bad == 0) fb = r;
          ni_bad++;
        end
      end
      if (fb < 0) fb = 0;
      `TB_CHECK(ni_bad == 0, ("cycle %0d: %0d NIs where bypass writes and the NI lookaheads disagree; first R%0d, write %0d, latest announcement cycles %0d..%0d",
                              c, ni_bad, fb, ej_v[fb], ni_beg[fb], ni_end[fb]))
      prev      = s0;
      have_prev = 1'b1;
    endfunction
  endclass

  mchk the_mchk;
  /* verilator lint_on UNUSEDSIGNAL */

endpackage

// =============================================================================
// ==== tb/checkers/ctrl_checker.sv
// =============================================================================
`timescale 1ns/1ps
// `include "tb_macros.svh": inlined earlier in this bundle

package cchk_pkg;
  import noc_pkg::*;
  import sched_ref_pkg::*;

  /* verilator lint_off UNUSEDSIGNAL */

  localparam int MAXN  = 256;               // tiles
  localparam int MAXVC = MAXN * 5 * 4;      // input VCs
  localparam int DMMAX = (1 << 14) - 1;     // a saturated demand sum (D17)

  class cchk;
    int     n, nn, rg, nvc, ep, ad, cs, by;
    longint lep, lcs, lcs6, lad, lad1;      // the same as longint (README rule 9)
    bit     started;
    longint c0;
    flit_t   fl  [MAXN * 5];
    credit_t cr  [MAXN * 5];
    int      rcl [MAXN], rcg [MAXN];        // the RTL's latched sums
    int      rpl [MAXN];                    // each tile's plan
    longint  rsl, rsg;                      // the controller's sums
    int      rkc;                           // the controller's plan
    int      pol;
    bit      damp;
    int      kmin, kmax;                    // the clamp (mesh_top's K_LO, K_HI)
    bit      occ [MAXVC], loc [MAXVC];
    int      acl [MAXN], acg [MAXN], lcl [MAXN], lcg [MAXN];
    longint  scl, scg;                      // mesh-wide latched sums
    int      k_cur, k_exp;                  // the plan in force, the one this epoch sets
    int      arr_max;                       // latest arrival of a new plan seen
    longint  n_epochs, n_changed, n_sat;
    int      k_lo, k_hi;                    // smallest and largest plan seen
    int      first_bad [MAXN];              // per tile: last cycle of this epoch without the new plan
    int      kq  [$];
    int      qq  [$];
    longint  slq [$], sgq [$];
    int      mxq [$];
    int      mx_tile;                       // largest latched sum of one tile, this epoch

    function new(int n_c, int rg_c, int nvc_c, int ep_c, int ad_c, int k0, int kmin_c = 1, int kmax_c = -1);
      int nn2, l;
      n       = n_c;
      nn      = n * n;
      rg      = rg_c;
      nvc     = nvc_c;
      ep      = ep_c;
      ad      = ad_c;
      nn2     = nn;
      l       = 0;
      for (int i = 0; i < 9; i++) begin
        if ((1 << l) < nn2) l++;
      end
      cs      = 2 * n + 14 + l;               // the sums are whole (D55), counted here
      by      = ref_plan_by(n);
      lep     = longint'(ep);
      lcs     = longint'(cs);
      lcs6    = lcs + 6;
      lad     = longint'(ad);
      lad1    = lad - 1;
      kmin    = kmin_c;
      kmax    = kmax_c;
      k_cur   = k0;
      k_exp   = k0;
      k_lo    = k0;
      k_hi    = k0;
      arr_max = 0;
      started = 1'b0;
      c0      = 0;
      rsl     = 0;
      rsg     = 0;
      rkc     = k0;
      pol     = 0;
      damp    = 1'b1;
      for (int i = 0; i < MAXN * 5; i++) begin
        fl[i] = '0;
        cr[i] = '0;
      end
      for (int r = 0; r < MAXN; r++) begin
        rcl[r] = 0;
        rcg[r] = 0;
        rpl[r] = k0;
      end
      for (int i = 0; i < MAXVC; i++) begin
        occ[i] = 1'b0;
        loc[i] = 1'b0;
      end
      for (int r = 0; r < MAXN; r++) begin
        acl[r] = 0;
        acg[r] = 0;
        lcl[r] = 0;
        lcg[r] = 0;
      end
    endfunction

    function bit same_reg(int d, int r);
      int dx, dy, rx, ry;
      dx = d % n;
      dy = d / n;
      rx = r % n;
      ry = r / n;
      return (dx / rg == rx / rg) && (dy / rg == ry / rg);
    endfunction

    function void step(longint c);
      longint e, ph, t;
      int     i, nl, ng, sl, sg, bad, fb, dst, vi, ci;
      bit     hd;
      head_t  h;
      if (!started) return;
      e  = c - c0;
      ph = e % lep;
      if (ph == 0) begin
        scl = 0;
        scg = 0;
        for (int r = 0; r < nn; r++) begin
          lcl[r] = acl[r];
          lcg[r] = acg[r];
          acl[r] = 0;
          acg[r] = 0;
          t      = longint'(lcl[r]);
          scl    = scl + t;
          t      = longint'(lcg[r]);
          scg    = scg + t;
          if (lcl[r] == DMMAX || lcg[r] == DMMAX) n_sat++;
          if (lcl[r] > mx_tile) mx_tile = lcl[r];
          if (lcg[r] > mx_tile) mx_tile = lcg[r];
          first_bad[r] = 0;
        end
        n_epochs++;
      end
      if (ph % 16 == 0) begin
        for (int r = 0; r < nn; r++) begin
          nl = 0;
          ng = 0;
          for (int k = 0; k < 5 * nvc; k++) begin
            i = r * 5 * nvc + k;
            if (occ[i] &&  loc[i]) nl++;
            if (occ[i] && !loc[i]) ng++;
          end
          sl = acl[r] + nl;
          sg = acg[r] + ng;
          if (sl > DMMAX) sl = DMMAX;
          if (sg > DMMAX) sg = DMMAX;
          acl[r] = sl;
          acg[r] = sg;
        end
      end
      if (ph == 1) begin
        bad = 0;
        fb  = -1;
        for (int r = 0; r < nn; r++) begin
          if (rcl[r] != lcl[r] || rcg[r] != lcg[r]) begin
            bad++;
            if (fb < 0) fb = r;
          end
        end
        `TB_CHECK(bad == 0, ("cycle %0d: %0d tiles latched other demand sums than the model; R%0d: local %0d cross-region %0d, model %0d %0d",
                             c, bad, fb, (fb < 0) ? 0 : rcl[fb], (fb < 0) ? 0 : rcg[fb], (fb < 0) ? 0 : lcl[fb], (fb < 0) ? 0 : lcg[fb]))
      end
      if (ph == lcs) begin
        `TB_CHECK(rsl == scl && rsg == scg, ("cycle %0d: the controller's sums are %0d and %0d, the tiles' latched sums add up to %0d and %0d",
                                             c, rsl, rsg, scl, scg))
      end
      if (ph == lcs6) begin
        k_exp = ref_next_kl(pol, damp, n, rg, scl, scg, k_cur, kmin, kmax);
      end
      if (ph > lcs6 && ph < lad) begin
        for (int r = 0; r < nn; r++) begin
          if (rpl[r] != k_exp) first_bad[r] = int'(ph);
        end
      end
      if (ph == lad1) begin
        `TB_CHECK(rkc == k_exp, ("cycle %0d: the controller's plan is %0d, expected %0d (sums %0d and %0d, policy %0d, damping %0d, last plan %0d)",
                                 c, rkc, k_exp, scl, scg, pol, damp, k_cur))
        bad = 0;
        fb  = -1;
        for (int r = 0; r < nn; r++) begin
          if (rpl[r] != k_exp) begin
            bad++;
            if (fb < 0) fb = r;
          end
        end
        `TB_CHECK(bad == 0, ("cycle %0d (the plan sample): %0d tiles do not have plan %0d; first R%0d with %0d",
                             c, bad, k_exp, fb, (fb < 0) ? 0 : rpl[fb]))
        if (k_exp != k_cur) begin
          i = 0;
          for (int r = 0; r < nn; r++) begin
            if (first_bad[r] + 1 > i) i = first_bad[r] + 1;
          end
          `TB_CHECK(i <= by, ("cycle %0d: the last tile had the new plan %0d only in cycle %0d of the epoch, expected by %0d",
                              c, k_exp, i, by))
          if (i > arr_max) arr_max = i;
          n_changed++;
        end
        k_cur = k_exp;
        if (k_cur < k_lo) k_lo = k_cur;
        if (k_cur > k_hi) k_hi = k_cur;
        kq.push_back(k_cur);
        qq.push_back(ref_bin(scl, scg));
        slq.push_back(scl);
        sgq.push_back(scg);
        mxq.push_back(mx_tile);
        mx_tile = 0;
      end
      for (int r = 0; r < nn; r++) begin
        for (int p = 0; p < 5; p++) begin
          i  = r * 5 + p;
          vi = int'(fl[i].vc);
          ci = int'(cr[i].vc);
          hd = fl[i].vld && !fl[i].byp && is_head(fl[i].ftype);
          if (hd) begin
            h   = head_t'(fl[i].data);
            dst = int'(h.dst);
            occ[i * nvc + vi] = 1'b1;
            loc[i * nvc + vi] = same_reg(dst, r);
          end
          if (cr[i].vld && cr[i].vc_free && !(hd && vi == ci)) begin
            occ[i * nvc + ci] = 1'b0;
          end
        end
      end
    endfunction

    function longint run_l();
      longint s, t;
      s = 0;
      for (int r = 0; r < nn; r++) begin
        t = longint'(acl[r]);
        s = s + t;
      end
      return s;
    endfunction

    function longint run_g();
      longint s, t;
      s = 0;
      for (int r = 0; r < nn; r++) begin
        t = longint'(acg[r]);
        s = s + t;
      end
      return s;
    endfunction
  endclass

  cchk the_cchk;

  /* verilator lint_on UNUSEDSIGNAL */

endpackage

